CREATE TABLE IF NOT EXISTS support_calls (linkedid VARCHAR(64) NOT NULL PRIMARY KEY, started_at DATETIME(3) NOT NULL, ended_at DATETIME(3) NOT NULL, kind VARCHAR(16) NOT NULL, grp VARCHAR(16) NOT NULL DEFAULT '', outcome VARCHAR(32) NOT NULL DEFAULT '', lost_reason VARCHAR(32) NOT NULL DEFAULT '', caller VARCHAR(80) NOT NULL DEFAULT '', caller_key VARCHAR(16) NOT NULL DEFAULT '', agent VARCHAR(32) NOT NULL DEFAULT '', trunk VARCHAR(64) NOT NULL DEFAULT '', destination VARCHAR(64) NOT NULL DEFAULT '', dial_status VARCHAR(16) NOT NULL DEFAULT '', announcement_s INT NULL, ring_s INT NULL, wait_s INT NULL, talk_s INT NULL, setup_s INT NULL, recorded TINYINT NOT NULL DEFAULT 0, quality VARCHAR(512) NOT NULL DEFAULT '', KEY idx_support_start(started_at), KEY idx_support_agent(agent,started_at), KEY idx_support_caller(caller_key,started_at));
CREATE TABLE IF NOT EXISTS support_agent_legs (linkedid VARCHAR(64) NOT NULL, seq SMALLINT NOT NULL, extension VARCHAR(32) NOT NULL, started_at DATETIME(3) NOT NULL, outcome VARCHAR(32) NOT NULL, ring_s INT NOT NULL, talk_s INT NOT NULL, PRIMARY KEY(linkedid,seq), KEY idx_support_leg_ext(extension,started_at));
CREATE TABLE IF NOT EXISTS support_ingest (id TINYINT NOT NULL PRIMARY KEY, cel_id BIGINT NOT NULL, updated_at DATETIME(3) NOT NULL)
